const $=id=>document.getElementById(id);let mode='auto',shape='rect',selected=null,rows=[],sortKey='R',sortDirection=-1;const numberFormats=new Map();const fmt=(v,n=2)=>{if(!numberFormats.has(n))numberFormats.set(n,new Intl.NumberFormat('en-US',{maximumFractionDigits:n,minimumFractionDigits:n}));return numberFormats.get(n).format(v);};
function calculate(q,a,b,t,e,l,kind=shape){const A=kind==='round'?Math.PI*(a/1000)**2/4:a*b/1e6,D=kind==='round'?a/1000:2*a*b/(a+b)/1000,V=q/A,T=t+273.15,rho=101325/(287.05*T),mu=1.716e-5*(T/273.15)**1.5*(273.15+110.4)/(T+110.4),Re=rho*V*D/mu;let f=64/Re;if(Re>=2300){f=.02;for(let i=0;i<30;i++)f=1/(-2*Math.log10(e/1000/(3.7*D)+2.51/(Re*Math.sqrt(f))))**2;}return{a,b,A,D,V,Re,f,R:f*rho*V*V/(2*D),loss:f*rho*V*V/(2*D)*l,de:kind==='round'?a:1.3*(a*b)**.625/(a+b)**.25,ratio:kind==='round'?1:Math.max(a,b)/Math.min(a,b)};}
function getInput(){return{q:+$('flow').value/+$('unit').value,v:+$('vmax').value,p:+$('pmax').value,l:+$('length').value,t:+$('temp').value,e:+$('material').value,a:+$('width').value,b:+$('height').value};}
function update(reselect=true){const x=getInput();if(reselect)selected=null;const valid=x.q>0&&Number.isFinite(x.q)&&x.v>0&&x.p>0&&x.l>=0&&x.t>=-20&&x.t<=60&&(mode==='auto'||(x.a>=50&&x.a<=5000&&(shape==='round'||x.b>=50&&x.b<=5000)));$('error').hidden=valid;if(!valid){$('error').textContent='Enter valid positive values. Temperature: −20 to 60 °C; duct dimensions: 50 to 5,000 mm.';clearResults();return;}rows=[];if(mode==='auto'){if(shape==='rect'){for(let a=100;a<=2000;a+=50)for(let b=100;b<=a;b+=50){if(a/b>4||x.q/(a*b/1e6)>x.v)continue;const r=calculate(x.q,a,b,x.t,x.e,x.l);if(r.V<=x.v&&r.R<=x.p)rows.push(r);}}else{for(let a=100;a<=2000;a+=50){if(x.q/(Math.PI*(a/1000)**2/4)>x.v)continue;const r=calculate(x.q,a,a,x.t,x.e,x.l);if(r.V<=x.v&&r.R<=x.p)rows.push(r);}}rows.sort((a,b)=>b.R-a.R||a.A-b.A||a.ratio-b.ratio);rows=rows.slice(0,10);if(rows.length)rows[0].recommended=true;sortRows();selected=rows.findIndex(r=>r.recommended);}else{const r=calculate(x.q,x.a,x.b,x.t,x.e,x.l);rows=[r];}if(!rows.length){$('error').hidden=false;$('error').textContent='No suitable sizes in the 100–2,000 mm range. Check the airflow or adjust the limits.';clearResults();return;}const r=rows[selected??0]||rows[0];render(r,x);renderTable();}
function renderTable(){$('candidate-count').textContent=mode==='auto'?rows.length.toLocaleString('en-US')+' suitable sizes':'1 size checked';$('candidates').innerHTML=rows.map((v,i)=>`<tr class="candidate ${(selected??0)===i?'chosen':''}"><td><button class="row-button" aria-pressed="${(selected??0)===i}" data-index="${i}" aria-label="Select size ${v.a} ${shape==='rect'?'by '+v.b:''}">${shape==='rect'?v.a+' × '+v.b:'Ø '+v.a}</button></td><td>${fmt(v.V)}</td><td>${fmt(v.R)}</td><td>${fmt(v.A,3)}</td><td>${shape==='rect'?fmt(v.ratio)+' : 1':'—'}</td><td><span class="badge ${v.recommended?'':'neutral'}">${mode==='check'?'Being checked':v.recommended?'Recommended':'Alternative'}</span></td></tr>`).join('');document.querySelectorAll('#candidates .candidate').forEach((tr,i)=>tr.onclick=()=>{selected=i;render(rows[i],getInput());document.querySelectorAll('#candidates .candidate').forEach((row,j)=>{row.classList.toggle('chosen',j===i);row.querySelector('button').setAttribute('aria-pressed',j===i);});});}
function clearResults(){$('candidate-count').textContent='0 suitable sizes';['size','area','equiv','ratio','velocity','friction','loss','reynolds','factor'].forEach(id=>$(id).textContent='—');$('status').textContent='No results yet';$('status').className='status warning';$('candidates').innerHTML='<tr><td colspan="6">No sizes to display.</td></tr>';$('chart').innerHTML='';$('vmeter').style.width=$('pmeter').style.width='0%';}
function render(r,x){$('size').innerHTML=(shape==='rect'?`${r.a} × ${r.b}`:`Ø ${r.a}`)+' <small>mm</small>';$('result-caption').textContent=mode==='auto'?(r.recommended?'RECOMMENDED DUCT SIZE':'SELECTED DUCT SIZE'):'DUCT SIZE TO CHECK';$('size-sub').textContent=(shape==='rect'?'Rectangular duct':'Round duct')+' · '+$('material').selectedOptions[0].textContent.split(' · ')[0];$('area').textContent=fmt(r.A,3)+' m²';$('equiv').textContent=fmt(r.de,0)+' mm';$('ratio').textContent=shape==='rect'?fmt(r.ratio)+' : 1':'—';$('velocity').textContent=fmt(r.V);$('friction').textContent=fmt(r.R);$('loss').textContent=fmt(r.loss,1);$('vdetail').textContent='Design limit: '+fmt(x.v,1)+' m/s';$('pdetail').textContent='Design limit: '+fmt(x.p,2)+' Pa/m';$('vmeter').style.width=Math.min(100,100*r.V/x.v)+'%';$('pmeter').style.width=Math.min(100,100*r.R/x.p)+'%';$('vmeter').style.background=r.V>x.v?'#db8a33':'#20b498';$('pmeter').style.background=r.R>x.p?'#db8a33':'#20b498';const warning=r.V>x.v||r.R>x.p||r.ratio>4||r.Re<4000;$('status').className='status'+(warning?' warning':'');$('status').textContent=r.ratio>4?'Aspect ratio > 4:1':r.Re<2300?'Laminar flow · approximate':r.Re<4000?'Transitional flow':warning?'Exceeds limits':'Within limits';$('reynolds').textContent='Re = '+fmt(r.Re,0);$('factor').textContent='Friction factor f = '+fmt(r.f,4);$('table-note').textContent=mode==='auto'?'Velocity ≤ '+fmt(x.v,1)+' m/s and friction ≤ '+fmt(x.p,2)+' Pa/m'+(shape==='rect'?' · Aspect ratio ≤ 4:1.':'.')+' Up to 10 sizes closest to the friction limit. Click a column heading to sort.':'Results for the internal dimensions entered.';$('duct').innerHTML=shape==='rect'?'<g fill="none" stroke="currentColor" stroke-width="1.5"><path d="M45 35l40-20h85v55l-40 23H45zM45 35h85v58M130 35l40-20M85 15v20"/><path d="M60 57h58m-8-6l8 6-8 6" stroke-width="2.5"/><path d="M44 103h86M34 35v58" stroke-dasharray="3 3"/></g>':'<g fill="none" stroke="currentColor" stroke-width="1.5"><ellipse cx="70" cy="65" rx="38" ry="34"/><path d="M70 31l60-18a38 34 0 0 1 10 66l-60 19M44 65h54m-8-6l8 6-8 6"/></g>';chart(r,x);}
function chart(r,x){const maxV=Math.max(r.V*1.5,x.v*1.15),maxQ=maxV*r.A*+$('unit').value,w=545,h=110,left=48,top=20,px=left+x.q/r.A/maxV*w,py=top+h-r.V/maxV*h;let grid='';for(let i=0;i<=4;i++){const y=top+h-i*h/4;grid+=`<line x1="${left}" x2="593" y1="${y}" y2="${y}" stroke="#e9eff1"/><text x="36" y="${y+4}" text-anchor="end" fill="#8b9ba6" font-size="11">${fmt(maxV*i/4,1)}</text><text x="${left+i*w/4}" y="152" text-anchor="middle" fill="#8b9ba6" font-size="11">${fmt(maxQ*i/4,0)}</text>`;}const limit=top+h-x.v/maxV*h;$('chart').innerHTML=`<defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#15b397" stop-opacity=".15"/><stop offset="1" stop-color="#15b397" stop-opacity="0"/></linearGradient></defs>${grid}<text x="48" y="10" fill="#899ba4" font-size="11">m/s</text><path d="M48 130L593 20L593 130Z" fill="url(#fill)"/><line x1="48" x2="593" y1="${limit}" y2="${limit}" stroke="#a9bdc4" stroke-dasharray="4 4"/><path d="M48 130L593 20" stroke="#15aa91" stroke-width="2.5" fill="none"/><line x1="${px}" x2="${px}" y1="${py}" y2="130" stroke="#15aa91" stroke-dasharray="4 4"/><circle cx="${px}" cy="${py}" r="5" fill="#10a68c" stroke="white" stroke-width="3"/><text x="${Math.min(px+10,535)}" y="${Math.max(py-10,15)}" fill="#078b75" font-size="12">${fmt(r.V)} m/s</text><text x="593" y="172" text-anchor="end" fill="#899ba4" font-size="11">Airflow (${$('unit').selectedOptions[0].textContent})</text>`;}
document.querySelectorAll('#modes button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('#modes button').forEach(v=>v.classList.toggle('selected',v===b));document.querySelector('.auto-fields').hidden=mode==='check';document.querySelector('.preset-fields').hidden=mode==='check';document.querySelector('.check-fields').hidden=mode==='auto';update();});document.querySelectorAll('#shapes button').forEach(b=>b.onclick=()=>{shape=b.dataset.shape;document.querySelectorAll('#shapes button').forEach(v=>v.classList.toggle('selected',v===b));$('width-label').textContent=shape==='round'?'Diameter':'Width';$('height-field').hidden=shape==='round';update();});let priorUnit=3600;$('unit').addEventListener('change',()=>{const current=+$('unit').value;$('flow').value=+(+$('flow').value/priorUnit*current).toFixed(4);priorUnit=current;update();});document.querySelectorAll('input, #material').forEach(el=>el.addEventListener('input',()=>update()));$('reset').onclick=()=>{Object.entries({flow:2000,unit:3600,vmax:10,pmax:1,width:500,height:300,length:10,temp:20,material:.09}).forEach(([id,val])=>$(id).value=val);priorUnit=3600;$('preset').value='standard';document.querySelector('#modes button[data-mode="auto"]').click();document.querySelector('#shapes button[data-shape="rect"]').click();};update();

function sortRows(){rows.sort((a,b)=>{const difference=sortKey==='size'?(a.a-b.a||a.b-b.b):sortKey==='assessment'?(Number(!a.recommended)-Number(!b.recommended)):(a[sortKey]-b[sortKey]);return sortDirection*(difference||a.a-b.a||a.b-b.b);});updateSortHeaders();}
function updateSortHeaders(){document.querySelectorAll('.sort-button').forEach(button=>{const active=button.dataset.sort===sortKey;button.closest('th').setAttribute('aria-sort',active?(sortDirection===1?'ascending':'descending'):'none');button.querySelector('.sort-icon').textContent=active?(sortDirection===1?'↑':'↓'):'↕';});}
document.querySelectorAll('.sort-button').forEach(button=>button.onclick=()=>{const chosen=rows[selected??0];if(sortKey===button.dataset.sort)sortDirection*=-1;else{sortKey=button.dataset.sort;sortDirection=1;}sortRows();if(chosen){selected=rows.indexOf(chosen);renderTable();render(chosen,getInput());}document.querySelector('.table-wrap').scrollTop=0;});updateSortHeaders();

const ductPresets={standard:{velocity:10,friction:1},smoke:{velocity:15,friction:3}};
$('preset').addEventListener('change',()=>{const preset=ductPresets[$('preset').value];if(preset){$('vmax').value=preset.velocity;$('pmax').value=preset.friction;update();}});
['vmax','pmax'].forEach(id=>$(id).addEventListener('input',()=>{$('preset').value='custom';}));
